def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    op.add_column('authors', sa.Column('user_id', sa.BigInteger(), nullable=True))
    op.add_column('authors', sa.Column('is_anonymous', sa.Boolean(), nullable=False, server_default='true'))
    op.create_foreign_key(None, 'authors', 'users', ['user_id'], ['id'])
    op.add_column('users', sa.Column('author_id', sa.BigInteger(), nullable=True))
    op.create_foreign_key(None, 'users', 'authors', ['author_id'], ['id'])
    
    # Créer automatiquement un Author pour chaque User existant
    conn = op.get_bind()
    
    # Récupérer tous les users existants
    users = conn.execute(sa.text("SELECT id, email FROM users")).fetchall()
    
    # Obtenir le prochain ID disponible dans authors
    max_author_id = conn.execute(sa.text("SELECT COALESCE(MAX(id), 0) FROM authors")).scalar()
    next_author_id = max_author_id + 1
    
    # Créer un Author vide pour chaque User
    for i, user in enumerate(users):
        author_id = next_author_id + i
        
        # Créer l'Author avec un ID spécifique
        conn.execute(sa.text("""
            INSERT INTO authors (id, user_id, is_anonymous, name) 
            VALUES (:author_id, :user_id, true, NULL)
        """), {"author_id": author_id, "user_id": user.id})
        
        # Lier l'User à son Author
        conn.execute(sa.text("""
            UPDATE users SET author_id = :author_id WHERE id = :user_id
        """), {"author_id": author_id, "user_id": user.id})
    
    # Mettre à jour la séquence authors_id_seq si elle existe
    if users:
        new_seq_value = next_author_id + len(users)
        conn.execute(sa.text(f"SELECT setval('authors_id_seq', {new_seq_value}, false)"))
    
    # ### end Alembic commands ###


